mapper.update:
update
CHB_INVESTHOLD_INFO_CHECK
set OPERATE_STATUS='01',
MERGER_INDENTIFY_MARK=(select MERGER_INDENTIFY_MARK from chb_equ_hold_check where
chb_equ_hold_check.INDENTIFY_MARK=CHB_INVESTHOLD_INFO_CHECK.INDENTIFY_MARK
and chb_equ_hold_check.REGIST_BANK_CODE=CHB_INVESTHOLD_INFO_CHECK.REGIST_BANK_CODE)
where 1=1
and  REGIST_BANK_CODE=#{registBankCode,jdbcType=VARCHAR}
and  (INDENTIFY_MARK=#{indentifyMark,jdbcType=VARCHAR})

	and PRD_REGIST_CODE=#{prdRegistCode,jdbcType=VARCHAR}


	and HOLD_DATE=#{holdDate,jdbcType=TIMESTAMP}


	and CCY=#{ccy,jdbcType=VARCHAR}


	and AMOUNT=#{amount,jdbcType=DECIMAL}


	and QTY=#{qty,jdbcType=DECIMAL}


	and CNY_AMT=#{cnyAmt,jdbcType=DECIMAL}


	and REMARK=#{remark,jdbcType=VARCHAR}


	and DATA_SOURCE=#{dataSource,jdbcType=CHAR}


	and STATUS=#{status,jdbcType=VARCHAR}


	and WORKFLOW_ID=#{workflowId,jdbcType=VARCHAR}


	and ORG_CODE=#{orgCode,jdbcType=VARCHAR}


	and DEPT_CODE=#{deptCode,jdbcType=VARCHAR}


	and AGENT=#{agent,jdbcType=VARCHAR}


	and PRODID=#{prodid,jdbcType=VARCHAR}


	and INTERF_CHECK_RESULT=#{interfCheckResult,jdbcType=VARCHAR}

mapper.delete:
delete from CHB_INVESTHOLD_INFO
where INDENTIFY_MARK in
(select INDENTIFY_MARK from CHB_EQU_HOLD hold
where hold.IDENTIFY_NUMBER = #{identifyNumber,jdbcType=VARCHAR}
AND hold.HOLDER_NAME = #{holderName,jdbcType=VARCHAR}

	AND hold.PERSONAL_IDENTIFY_TYPE = #{personalIdentifyType,jdbcType=VARCHAR}


	AND hold.INSTITUTION_IDENTIFY_TYPE=#{institutionIdentifyType,jdbcType=VARCHAR}


	AND hold.OTHER_IDENTIFY_NAME=#{otherIdentifyName,jdbcType=VARCHAR}
)

mapper.select:
select
si.REGIST_BANK_CODE, si.INDENTIFY_MARK,si.PRD_REGIST_CODE,
si.HOLD_DATE, si.CCY, si.AMOUNT,
si.QTY, si.CNY_AMT, si.REMARK,
si.DATA_SOURCE, si.STATUS, si.WORKFLOW_ID,
si.ORG_CODE, si.DEPT_CODE, si.UPDATE_USER,
si.UPDATE_TIME, si.CREATE_USER, si.CREATE_TIME,
si.AGENT, si.CREATE_DEPT, si.PRODID,
si.INTERF_CHECK_RESULT
from CHB_INVESTHOLD_INFO si
inner join CHB_INVESTHOLD_INFO_SUB ss
on si.REGIST_BANK_CODE=ss.REGIST_BANK_CODE
and si.INDENTIFY_MARK=ss.INDENTIFY_MARK
and si.HOLD_DATE=ss.HOLD_DATE
and si.CCY=ss.CCY
and si.PRODID=ss.PRODID
where 1=1
and ss.SEND_STATUS='01'

	and  si.REGIST_BANK_CODE=#{registBankCode,jdbcType=VARCHAR}


	and si.INDENTIFY_MARK=#{indentifyMark,jdbcType=VARCHAR}


	and si.PRD_REGIST_CODE=#{prdRegistCode,jdbcType=VARCHAR}


	and si.HOLD_DATE=#{holdDate,jdbcType=TIMESTAMP}


	and si.CCY=#{ccy,jdbcType=VARCHAR}


	and si.AMOUNT=#{amount,jdbcType=DECIMAL}


	and si.QTY=#{qty,jdbcType=DECIMAL}


	and si.CNY_AMT=#{cnyAmt,jdbcType=DECIMAL}


	and si.REMARK=#{remark,jdbcType=VARCHAR}


	and si.DATA_SOURCE=#{dataSource,jdbcType=CHAR}


	and si.STATUS=#{status,jdbcType=VARCHAR}


	and si.WORKFLOW_ID=#{workflowId,jdbcType=VARCHAR}


	and si.ORG_CODE=#{orgCode,jdbcType=VARCHAR}


	and si.DEPT_CODE=#{deptCode,jdbcType=VARCHAR}


	and si.AGENT=#{agent,jdbcType=VARCHAR}


	and si.PRODID=#{prodid,jdbcType=VARCHAR}


	and si.INTERF_CHECK_RESULT=#{interfCheckResult,jdbcType=VARCHAR}

