update CHB_INVESTHOLD_INFO_CHECK
set MERGER_INDENTIFY_MARK = #{mergerindentifymark,jdbcType=VARCHAR},
OPERATE_STATUS = #{operatestatus,jdbcType=VARCHAR},
UPDATE_TIME = sysdate

	,UPDATE_USER = #{updateUser,jdbcType=VARCHAR}

where INDENTIFY_MARK in
(select INDENTIFY_MARK from CHB_EQU_HOLD hold
