)

update CHB_INVESTHOLD_INFO_SUB
set INDENTIFY_MARK = #{mergerindentifymark,jdbcType=VARCHAR}
where INDENTIFY_MARK=#{indentifyMark,jdbcType=VARCHAR}
and SEND_STATUS = '01'

mapper.select:
SELECT s1.* FROM CHB_INVESTHOLD_INFO s1 INNER join( select cs.INDENTIFY_MARK,CS.REGIST_BANK_CODE,CS.CCY,CS.HOLD_DATE,cs.PRODID from CHB_INVESTHOLD_INFO_sub cs inner join chb_equ_hold_check cc on CC.INDENTIFY_MARK=cs.INDENTIFY_MARK and CC.REGIST_BANK_CODE=CS.REGIST_BANK_CODE where SEND_STATUS='01' )s2 on s1.REGIST_BANK_CODE=s2.REGIST_BANK_CODE and s1.INDENTIFY_MARK=s2.INDENTIFY_MARK and s1.CCY=s2.CCY and s1.HOLD_DATE=s2.HOLD_DATE and s1.PRODID=s2.PRODID where s1.status='E'
AND concat_ws('_',s1.REGIST_BANK_CODE,s1.INDENTIFY_MARK,s1.CCY,s1.HOLD_DATE,s1.PRODID) IN
#{key,jdbcType=VARCHAR}

select s1.REGIST_BANK_CODE, s1.INDENTIFY_MARK,s1.PRD_REGIST_CODE, s1.HOLD_DATE, s1.CCY, s1.AMOUNT, s1.QTY, s1.CNY_AMT, s1.REMARK, s1.DATA_SOURCE, s1.STATUS, s1.WORKFLOW_ID, s1.ORG_CODE, s1.DEPT_CODE, s1.UPDATE_USER, s1.UPDATE_TIME, s1.CREATE_USER, s1.CREATE_TIME, s1.AGENT, s1.CREATE_DEPT, s1.PRODID, s1.INTERF_CHECK_RESULT from CHB_INVESTHOLD_INFO s1 inner join CHB_INVESTHOLD_INFO_sub cc on s1.REGIST_BANK_CODE=cc.REGIST_BANK_CODE and s1.INDENTIFY_MARK=cc.INDENTIFY_MARK and s1.CCY=cc.CCY and s1.HOLD_DATE=cc.HOLD_DATE and s1.PRODID=cc.PRODID where s1.status='E' and cc.SEND_STATUS='01' and s1.INDENTIFY_MARK in (select INDENTIFY_MARK from CHB_EQU_HOLD_CHECK UNION all select ORG_INDENTIFY_MARK from CHB_EQU_HOLD_CHECK where ORG_INDENTIFY_MARK is not null) and s1.INDENTIFY_MARK not in (select INDENTIFY_MARK from CHB_EQU_HOLD )
AND concat_ws('_',s1.REGIST_BANK_CODE,s1.INDENTIFY_MARK,s1.CCY,s1.HOLD_DATE,s1.PRODID) IN
#{key,jdbcType=VARCHAR}

SELECT * from CHB_INVESTHOLD_INFO_sub where SEND_STATUS='01'
AND concat_ws('_',REGIST_BANK_CODE,INDENTIFY_MARK,CCY,DATE_FORMAT(HOLD_DATE,'%Y-%m-%d'),PRODID) IN
#{key,jdbcType=VARCHAR}

	SELECT
	   COUNT(1)
	FROM CHB_INVESTHOLD_INFO_SUB SUB

    INNER JOIN CHB_SUBMIT_STATUS CSS
    ON SUB.SUMIT_SEQ = CSS.SEQNO
    AND CSS.SUBMIT_FEEDBACK_STATUS = '03'

    WHERE 1=1
	AND SUB.REGIST_BANK_CODE =#{registBankCode,jdbcType=VARCHAR}
    and SUB.INDENTIFY_MARK = #{indentifyMark,jdbcType=VARCHAR}
    and SUB.CCY =  #{ccy,jdbcType=VARCHAR}
    and SUB.HOLD_DATE = #{holdDate,jdbcType=DATE}
    and SUB.PRODID = #{prodid,jdbcType=VARCHAR}

